create table wksp_mlegenai.sm_reactions (
    id         number generated by default on null as identity not null enable,
    post_id    number,
    reaction   varchar2(16 char),
    lat        number,
    lon        number,
    created    date not null enable,
    created_by varchar2(255 char) not null enable,
    updated    date not null enable,
    updated_by varchar2(255 char) not null enable
);

alter table wksp_mlegenai.sm_reactions
    add constraint sm_reactions_id_pk primary key ( id )
        using index enable;


